import{c as a,Q as s,j as e,m as l}from"./chunks/framework.DOi4mjdC.js";const n="/assets/zh-cn_formulaimage_0000002353089833.B2PYRcvZ.png",r="/assets/zh-cn_formulaimage_0000001697647873.CwvmslbA.png",d="data:image/png;base64,",b=JSON.parse('{"title":"FasterGelu","description":"","frontmatter":{},"headers":[{"level":1,"title":"FasterGelu","slug":"fastergelu"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/激活函数/Gelu接口/FasterGelu.md","filePath":"api/SIMD-API/高阶API/激活函数/Gelu接口/FasterGelu.md"}'),o={name:"api/SIMD-API/高阶API/激活函数/Gelu接口/FasterGelu.md"};function i(p,t,c,A,u,g){return s(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="fastergelu" tabindex="-1">FasterGelu <a class="header-anchor" href="#fastergelu" aria-label="Permalink to &quot;FasterGelu&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>在神经网络中，GELU是一个重要的激活函数，其灵感来源于relu和dropout，在激活中引入了随机正则的思想。为了降低GELU的算力需求，业界提出了FastGelu等版本。本接口FasterGelu是针对FastGelu的化简版本，公式化简可以大幅度提升计算性能。计算公式如下:</p><p><img src="'+n+'" alt=""></p><p><img src="'+r+'" alt="">，化简后可得<img src="'+d+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool highPrecision = false, bool highPerformance = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void FasterGelu(const LocalTensor&lt;T&gt;&amp; dstLocal, const LocalTensor&lt;T&gt;&amp; srcLocal, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const uint32_t dataSize)</span></span></code></pre></div></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool highPrecision = false, bool highPerformance = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void FasterGelu(const LocalTensor&lt;T&gt;&amp; dstLocal, const LocalTensor&lt;T&gt;&amp; srcLocal, const uint32_t dataSize)</span></span></code></pre></div></li></ul><p>由于该接口的内部实现中涉及复杂的数学计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间支持开发者<strong>通过sharedTmpBuffer入参传入</strong>和<strong>接口框架申请</strong>两种方式。</p><ul><li>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</li><li>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</li></ul><p>通过sharedTmpBuffer传入的情况，开发者需要为tensor申请空间；接口框架申请的方式，开发者需要预留临时空间。临时空间大小BufferSize的获取方式如下：通过<a href="./GetGeluMaxMinTmpSize.html">GetGeluMaxMinTmpSize</a>中提供的接口获取需要预留空间范围的大小。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。支持的数据类型为：half、float。</td></tr><tr><td>highPrecision</td><td>是否使能高精度模式，以提升运算准确度。默认值为false，表示不使能高精度模式。 注意：高精度模式只在half数据类型下使能后生效，该参数的取值不影响float数据类型下的接口精度和性能。</td></tr><tr><td>highPerformance</td><td>是否使能高性能模式，以提升运算效率。默认值为false，表示不使能高性能模式。 注意：开启高性能模式相比于默认不开启高精度和高性能模式会有精度下降，同时开启高精度和高性能模式相比于仅开启高性能模式可能会有性能下降。针对Ascend 950PR/Ascend 950DT，该参数保留但不生效，取值为true或者false，接口的精度和性能没有区别。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstLocal</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>srcLocal</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时缓存。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 用于接口内部复杂计算时存储中间变量，由开发者提供。 临时空间大小BufferSize的获取方式请参考GetGeluMaxMinTmpSize。</td></tr><tr><td>dataSize</td><td>输入</td><td>实际计算数据元素个数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>源操作数和目的操作数的Tensor空间可以复用。</li><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>当前仅支持ND格式的输入，不支持其他格式。</li><li>不支持sharedTmpBuffer与源操作数和目的操作数地址重叠。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal：输出Tensor</span></span>
<span class="line"><span>// srcLocal：输入Tensor</span></span>
<span class="line"><span>// dataSize：实际参与计算的元素个数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 默认不开启高精度和高性能模式</span></span>
<span class="line"><span>AscendC::FasterGelu(dstLocal, srcLocal, dataSize);</span></span>
<span class="line"><span>// 开启高精度模式，高精度模式只在srcType为half时生效</span></span>
<span class="line"><span>AscendC::FasterGelu&lt;srcType, true, false&gt;(dstLocal, srcLocal, dataSize);</span></span>
<span class="line"><span>// 开启高性能模式</span></span>
<span class="line"><span>AscendC::FasterGelu&lt;srcType, false, true&gt;(dstLocal, srcLocal, dataSize);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(srcLocal): [-1.83887 -3.60742 3.12891 -0.620605 2.0625 -2.77344 -0.04422 -3.54297 -3.16211 2.67383 1.3291 -1.57617 -0.0123901 3.77539 -1.61621 -0.616699]</span></span>
<span class="line"><span>输出数据(dstLocal): [-0.0769653 -0.00775528 3.11328 -0.160034 2.00195 -0.0244446 -0.021286 -0.00849152 -0.0144653 2.64453 1.20312 -0.100769 -0.00613022 3.76758 -0.0969238 -0.159912]</span></span></code></pre></div>`,25)])])}const m=a(o,[["render",i]]);export{b as __pageData,m as default};
